#!/usr/bin/env bash
# Vicbless: favicon, app icons and the link-preview (social) image. Run from the REPO ROOT:  bash add-vicbless-brand-images.sh
# Adds to frontend/public/ (Vite copies this folder into the site as-is):
#   favicon.ico  favicon.svg  apple-touch-icon.png  icon-192.png  icon-512.png  icon-maskable-512.png
#   og-image.png (1200x630, the picture shown when the link is shared)  site.webmanifest
# and puts the matching tags in frontend/index.html. All of it is drawn from the approved logo (the V and B letters).
# It never replaces an image you already have that differs from mine (FORCE=1 does). Safe to run twice. Runs no git commands.
set -euo pipefail
if [ ! -d .git ] || [ ! -f frontend/index.html ]; then
  echo "Run this from the root of the vicbless-booking-platform repo (the folder with .git and frontend/)."
  exit 1
fi
command -v python3 >/dev/null || { echo "python3 is needed to run this script."; exit 1; }
STAGE="$(mktemp -d)"
trap 'rm -rf "$STAGE"' EXIT
base64 -d > "$STAGE/apple-touch-icon.png" <<'VICBLESS_EOF'
