    <meta name="description" content="Book a haircut at Vicbless Barbershop in Baxley, GA. Pick a service, choose a time, done." />
    <!-- Icons. The .ico is for old browsers, the .svg for modern ones, the apple one for iPhone home screens. -->
    <link rel="icon" href="/favicon.ico" sizes="48x48" />
    <link rel="icon" href="/favicon.svg" type="image/svg+xml" />
    <link rel="apple-touch-icon" href="/apple-touch-icon.png" />
    <link rel="manifest" href="/site.webmanifest" />
    <!-- Link previews (iMessage, Instagram, Facebook, X, Slack, WhatsApp). The image address has to be absolute. -->
    <meta property="og:type" content="website" />
    <meta property="og:site_name" content="Vicbless Barbershop" />
    <meta property="og:title" content="Vicbless Barbershop" />
    <meta property="og:description" content="Book a haircut online. Baxley, GA." />
    <meta property="og:url" content="https://vicbless.com/" />
    <meta property="og:image" content="https://vicbless.com/og-image.png" />
    <meta property="og:image:width" content="1200" />
    <meta property="og:image:height" content="630" />
    <meta property="og:image:alt" content="Vicbless Barbershop, Baxley, GA" />
    <meta name="twitter:card" content="summary_large_image" />
VICBLESS_EOF
export STAGE
python3 - <<'PY'
import os, sys
from pathlib import Path

stage = Path(os.environ["STAGE"]); force = os.environ.get("FORCE") == "1"
pub = Path("frontend/public"); pub.mkdir(parents=True, exist_ok=True)

# 1. The image files. A file that is already identical is skipped, one that differs is left alone unless FORCE=1.
wrote, kept = [], []
for src in sorted(stage.iterdir()):
    if src.name == "head.html":
        continue
    dst = pub / src.name
    new = src.read_bytes()
    if dst.exists():
        if dst.read_bytes() == new:
            continue
        if not force:
            kept.append(str(dst)); continue
    dst.write_bytes(new); wrote.append(str(dst))

# 2. The tags in index.html, added once, just before the Google Fonts lines.
index = Path("frontend/index.html"); html = index.read_text()
head = (stage / "head.html").read_text()
anchor = '    <link rel="preconnect" href="https://fonts.googleapis.com" />'
tagged = False
if 'rel="manifest"' in html or 'property="og:image"' in html:
    print("index.html already has icon or preview tags. Left alone.")
elif anchor in html:
    index.write_text(html.replace(anchor, head + "\n" + anchor, 1)); tagged = True
else:
    print("Could not find the spot in frontend/index.html (it was edited). Paste this inside <head> yourself:\n")
    print(head)

print("Wrote:" if wrote else "No image files needed writing.")
for w in wrote: print("  -", w)
if tagged: print("  - frontend/index.html (tags added)")
if kept:
    print("Left alone (different from mine, FORCE=1 overwrites):")
    for k in kept: print("  -", k)
PY
echo
echo "Next: cd frontend && npm run build, then check dist/ has favicon.ico, og-image.png and the rest."
echo "Then:  git add -A && git commit  (the Deploy frontend workflow publishes it)"
